cd ~/captures; cat > /tmp/c.py <<'EOF'
from PIL import Image; import sys
for f in sys.argv[1:]:
  im=Image.open(f).convert('L'); W,H=im.size; p=im.load()
  seen=set()
  for y in range(H):
    for x in range(W):
      if p[x,y]<60 and (x,y) not in seen:
        st=[(x,y)];seen.add((x,y));pts=[]
        while st:
          a,b=st.pop();pts.append((a,b))
          for c,d in((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
            if 0<=c<W and 0<=d<H and (c,d) not in seen and p[c,d]<60: seen.add((c,d));st.append((c,d))
        if len(pts)<5000:
          # weighted with darkness incl. border
          print(f,len(pts),sum(q[0] for q in pts)/len(pts),sum(q[1] for q in pts)/len(pts))
EOF
